 checks.push(['TTS',!writerModuleOn(plugin,'tts')?writerUi('Oculto','Hidden'):
  nativeSpeech?writerUi('API Web Speech disponível','Web Speech API exposed'):writerUi('API Web Speech indisponível','Web Speech API unavailable')]);
