   if(view.app.vault.getAbstractFileByPath(path))throw Error(writerUi('Nota já existente.','Note already exists.'));
   const body='---\ntags:\n  - '+tag+'\n---\n\n# '+name+'\n';
   const file=await view.app.vault.create(path,body);
