 if(!nums.length)return null;
 const sum=nums.reduce((a,b)=>a+b,0);
 return rollup.op==='sum'?sum:rollup.op==='avg'?Math.round(sum/nums.length*100)/100:rollup.op==='min'?Math.min(...nums):Math.max(...nums);
