 plugin.addCommand({id:'v11-property-editor',name:writerUi('Bancos: editar propriedade tipada','Databases: edit typed property'),
  callback:()=>writerV11DbPropertyModal(plugin,plugin.app.workspace.getActiveFile?.())});
