 const onTransition=event=>{if(event.target?.matches?.(geometry))scheduleLayout();};
 let lastPath=null;
 const onFile=()=>{
  scheduleLayout();
  if(!row)return;
  const path=ws.getActiveFile?.()?.path;
  if(path!==lastPath){show(word);show(read);show(mode);lastPath=path;}
  queue();
 };
